public class RootHidProvider extends ContentProvider {
 static volatile IBinder hid;public boolean onCreate(){return true;}public Bundle call(String method,String arg,Bundle extras){if(Binder.getCallingUid()!=0&&Binder.getCallingUid()!=android.os.Process.myUid())throw new SecurityException("Root only");if(!"binder".equals(method))throw new IllegalArgumentException("Unsupported operation");Bundle result=new Bundle();result.putBinder("hid",hid);result.putInt("uid",getContext().getApplicationInfo().uid);return result;}public Cursor query(Uri u,String[] p,String s,String[] a,String sort){throw new UnsupportedOperationException();}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
}
